::v-deep .el-dialog__title{
  position: relative;
  padding-left: 12px;
}
::v-deep .el-dialog__title::before{
  content: '';
    position: absolute;
    left: 0px;
    top: 1px;
    width: 0px;
    height: 100%;
    border-left: 4px solid;
    z-index: 9;
    margin-right: 4px;
    color: #1061ff;
    // color: #409EFF;
}
.item_status{
  font-size: 15px;
  color: #fff;

  display: inline-block;
  padding: 1px 5px;
  border-radius: 2px;
  margin-right: 10px;
  white-space: nowrap;
}
.item_status.item_status0{
  background: #ffb800;
}
.item_status.item_status1{
  background: #00c868;
}
.item_status.item_status2{
  background: #c4c4c4;
}
.item_status.item_status3{
  background: #c4c4c4;
}


::v-deep{
  .el-dialog__header{
    padding: 20px 30px 10px
  }
  .el-dialog__body{
    padding: 15px 30px 15px;
  }
}
.question_detail{
  height: 75vh;
  overflow: auto;
  .question_title{
    font-size: 20px;
    font-family: '黑体';
    font-weight: bold;
    line-height: 22px;
    color: #000;
    margin-bottom: 20px
  }
  .question_time{
    font-size: 14px;
    line-height: 22px;
    color: #1061ff;
    margin-bottom: 20px
  }
  .question_describe{
    border-radius: 2px;
    background-color: #ecf5ff;
    padding: 15px;
    font-size: 14px;
    margin-bottom: 20px;
    .describe_title{
      color:#1061ff;
      line-height:22px;
      margin-bottom: 5px;
    }
    .describe_content{
      margin-bottom: 30px
    }
    .describe_img{
      .img_item{
        border: 1px solid #9d9d9d;
        display: inline-block;
        margin-right: 15px;
        border-radius: 2px;
        padding: 5px
      }
    }

    .describe_line2{
      display: flex;
      height: 40px;
      .describe_title{
        line-height: 40px;
      }
      .describe_content{
        margin-bottom: 10px;
      }
    }
  }
  .shengTit{
    font-size: 16px;
    margin-bottom: 20px;
  }
  .question_icon{
    font-size: 28px;
    text-align: center;
    margin: 0 0 10px 0;
    cursor: pointer;
  }
  .question_wrap{
    // display: flex;
  }
  .question_wrap_l{
    width: 90px;
    text-align: center;
    font-size: 15px;
    margin-top: 1px;
    margin-bottom: 15px;
  }
  .question_info{
    display: flex;
    flex-wrap: wrap;
    // margin-bottom: 15px;
    .question_info_name{
      display: inline-block;
      width: 95px;
      text-align: right;
      // margin-right: 5px;
    }
    .question_info_name2{
      text-align: right;
    }
    .info_item{
      // width: 33.33%;
      width: 25%;
      display: flex;
      // align-items: center;
      color: #333;
      font-size: 15px;
      line-height: 22px;
      margin-bottom: 25px;
      padding-right: 10px;
      box-sizing: border-box;
      img{
        margin-right: 10px;
        width: 18px;
        height: 18px;
        margin-top: 3px;
      }
    }
    .info_item2{
      width: 100%;
      display: flex;
      .ww1{
        width: 100px;
      }
      .ww2{
        flex: 1;
      }
    }
  }
  .question_info2{
    border-top: 2px solid #e9e9e9;
    margin-bottom: 15px;
    padding-top: 23px;
  }
  .process_box{
    position: relative;
    .process_title{
      span{display: inline-block}
      .title_logo{
        height: 55px; width: 55px;
        border-radius: 50%;
        border: 1px solid #1061ff;
        color: #1061ff;
        text-align: center;
        line-height: 49px;
        font-size: 25px
      }
      .title{
        color: #000;
        font-family: '黑体';
        font-size: 22px;
        font-weight: bold;
        margin-left: 20px;
      }
    }

    .process_item{
      padding-left: 70px;
      .process_item_line{
        position: absolute;
        width: 100px;
        border-bottom: 1px #1061ff dashed;
        border-left: 1px #1061ff dashed;
        left: 25px;
      }
      .process_item_body{
        background-color: #fafafa;
        border: 1px solid #efefef;
        border-radius: 4px;
        margin-bottom: 30px;
        padding: 15px;
        display: flex;
        position: relative;
        padding-left: 50px;
        .item_icon{
          position: absolute;
          left: -6px;
          top: 28px;
          display: flex;
          align-items: center;

        }
        .item_content{
          .content_top{
            color: #000;
            font-size: 16px;
            font-weight: bold;
            font-family: '黑体';
            .content_top_text{
              font-size: 16px;
              display: inline-block;
              margin-left: 20px;
              color: #1061ff;
            }
          }
          .content_time{
            color: rgba(0,0,0, 0.5);
            font-size: 14px;
            line-height: 22px;
            margin-bottom: 15px;
          }
          .content_advice{
            color: rgba(0,0,0, 0.5);
            font-size: 14px;
            line-height: 22px;

          }
        }
      }
    }
    .process_item:nth-child(2) {
      .process_item_line{
        height: 38px;
      }
    }
    .process_item:nth-child(3) {
      .process_item_line{
        height: 135px;
        top: 96px;
      }
    }
    .process_item:nth-child(4) {
      .process_item_line{
        height: 135px;
        top: 235px;
      }
    }
  }
}
.btn_box{
  text-align: center
}
::-webkit-scrollbar{
  width: 5px;
  height: 5px;
}
::v-deep ::-webkit-scrollbar-button{
  display: none
}
::-webkit-scrollbar-thumb{
  background: #bed4ff;
  border-radius: 3px
}
::-webkit-scrollbar-track{
  margin: 5px
}
